import java.util.*;

class Solution {
    private int rev(int x) {
        int r = 0;
        while (x > 0) {
            r = r * 10 + x % 10;
            x /= 10;
        }
        return r;
    }

    public int countNicePairs(int[] nums) {
        Map<Integer, Integer> count = new HashMap<>();
        long ans = 0, MOD = 1_000_000_007L;
        for (int x : nums) {
            int diff = x - rev(x);
            int prev = count.getOrDefault(diff, 0);
            ans = (ans + prev) % MOD;
            count.put(diff, prev + 1);
        }
        return (int)ans;
    }
}

/**
 * @param {number[]} nums
 * @return {number}
