var countNicePairs = function(nums) {
    const rev = (x) => {
        let r = 0;
        while (x > 0) {
            r = r * 10 + (x % 10);
            x = Math.floor(x / 10);
        }
        return r;
    };

    const MOD = 1000000007n;
    const count = new Map();
    let ans = 0n;
    for (const x of nums) {
        const diff = x - rev(x);
        const prev = BigInt(count.get(diff) || 0);
        ans = (ans + prev) % MOD;
        count.set(diff, Number(prev) + 1);
    }
    return Number(ans);
};
